  const { instance } = await WebAssembly.instantiate(wasmBuf);
  const exports = instance.exports;

  const payload = JSON.stringify({
    path: "/secret/movie",
    payload: { tmdb: "27205" }
  });
  const encodedPayload = Buffer.from(payload, "utf8");
  const randBytes = crypto.randomBytes(44);

