  const outPtr = exports.alloc(outMaxLen);

  const mem = new Uint8Array(exports.memory.buffer);
  mem.set(encodedPayload, payloadPtr);
  mem.set(randBytes, randPtr);

  const sealedLen = exports.seal_request(
    payloadPtr, encodedPayload.length,
    randPtr, randBytes.length,
    outPtr, outMaxLen
  );

  console.log("Sealed length:", sealedLen);

  const sealedBuffer = Buffer.from(exports.memory.buffer, outPtr, sealedLen);

  const responseKey = sealedBuffer.subarray(0, 32);
  const keyId = sealedBuffer[32];
  const ephemeralPublic = sealedBuffer.subarray(33, 98);
  const ciphertextBody = sealedBuffer.subarray(98);

  console.log("responseKey len:", responseKey.length, "hex:", responseKey.toString("hex").slice(0, 16) + "...");
  console.log("keyId:", keyId);
  console.log("ephemeralPublic len:", ephemeralPublic.length, "hex prefix:", ephemeralPublic.subarray(0, 4).toString("hex"));
  console.log("ciphertextBody len:", ciphertextBody.length);

  // Free memory
  exports.dealloc(payloadPtr, encodedPayload.length);
  exports.dealloc(randPtr, randBytes.length);
  exports.dealloc(outPtr, outMaxLen);

  // Send request to api.wing.st/g
